"""The section-based TheQuizRealm homepage; source stays independent of games."""
from html import escape
import json
from pathlib import Path

def build_home(catalog, card, page):
    root=Path(__file__).resolve().parents[1]
    content=json.loads((root/'site/home.json').read_text(encoding='utf-8'))
    by_url={game['url']:game for game in catalog}
    jumps=''.join(f'<a href="#{section["id"]}">{escape(section["short"])}</a>' for section in content['sections'])
    body='''<section class="h-hero" aria-labelledby="home-title"><div class="h-hero-copy"><span class="h-eyebrow">THEQUIZREALM · FREE BROWSER GAMES</span><h1 id="home-title">Trivia, puzzles,<br>and a little <span>rivalry.</span></h1><p>Find a favourite. Learn something unexpected. From a quiet word puzzle to a lively quiz night, there’s a good game for every kind of break.</p><div class="h-actions"><a class="h-button" href="#trivia">Explore the games <span aria-hidden="true">↗</span></a><a class="h-button h-button-secondary" href="/group-hub.html">Play with friends</a></div><div class="h-assurances"><span>Free to play</span><span>No account needed</span><span>Progress saved on your device</span></div></div><aside class="h-daily" aria-labelledby="home-daily-title"><div class="h-daily-top"><span class="h-eyebrow">YOUR DAILY CHALLENGE</span><span class="h-daily-badge">10 QUESTIONS</span></div><div class="h-daily-art" aria-hidden="true"><span>?</span><span>10</span><span>✓</span></div><h2 id="home-daily-title">A fresh set.<br>A new favourite ritual.</h2><p>Science, history, culture, and a few surprises. Ten mixed questions, refreshed every day.</p><a class="h-button" href="/daily.html">Play the Daily Ten <span aria-hidden="true">↗</span></a><small>About 3–5 minutes · New set at midnight UTC</small></aside></section>'''
    body+='<nav class="h-category-nav" aria-label="Browse game sections"><span>Find your game</span>'+jumps+'<a href="#collections">Topic collections</a></nav>'
    for section in content['sections']:
        games=[by_url[url] for url in section['games']]
        body+=f'''<section class="h-game-section" id="{section['id']}" aria-labelledby="{section['id']}-title"><div class="h-section-head"><div><span class="h-eyebrow">{escape(section['eyebrow'])}</span><h2 id="{section['id']}-title">{escape(section['title'])}</h2><p>{escape(section['description'])}</p></div><a class="h-view-all" href="{section['link']}">{escape(section['linkLabel'])} <span aria-hidden="true">↗</span></a></div><div class="h-game-grid">'''+''.join(card(game,i) for i,game in enumerate(games))+'</div></section>'
        if section['id']=='words-logic':
            body+='''<section class="h-friends-banner"><div><span class="h-eyebrow">MAKE AN EVENING OF IT</span><h2>Good company.<br>Friendly competition.</h2><p>Pass a screen for a two-player duel, sketch a secret word, or host a trivia room for the whole group.</p></div><div><a class="h-button" href="/group-hub.html">Find a group game ↗</a><a class="h-inline-link" href="/host-a-better-quiz-night.html">Read the quiz-night guide</a></div></section>'''
    collections=json.loads((root/'site/collections.json').read_text(encoding='utf-8'))
    body+='''<section class="h-game-section" id="collections" aria-labelledby="collections-title"><div class="h-section-head"><div><span class="h-eyebrow">GO A LITTLE DEEPER</span><h2 id="collections-title">Explore by topic</h2><p>Games, background reading, and familiar favourites, brought together in one place.</p></div><a class="h-view-all" href="/directory.html#collections">All collections ↗</a></div><div class="h-collection-grid">'''
    for item in content['collections']:
        collection=collections[item['url']]
        image=item['image'];thumbnail='assets/thumbs/'+Path(image).stem+'.webp'
        if (root/thumbnail).exists():image=thumbnail
        body+=f'''<a class="h-collection" href="/{item['url']}"><img src="/{image}" alt="" width="160" height="120" loading="lazy"><div><h3>{escape(item['label'])}</h3><p>{escape(item['description'])}</p></div><span aria-hidden="true">↗</span></a>'''
    body+='</div></section>'
    body+='''<section class="h-notebook" aria-labelledby="notebook-title"><div class="h-section-head"><div><span class="h-eyebrow">GUIDES &amp; GOOD IDEAS</span><h2 id="notebook-title">A little more to explore</h2><p>Practical advice for the games you play and the people you play them with.</p></div><a class="h-view-all" href="/game-guides.html">All guides ↗</a></div><div class="h-guide-grid"><a href="/how-to-play-nexus-grid.html"><span>01 · PUZZLE GUIDE</span><h3>Find the connection</h3><p>How to spot a strong word group, work around a red herring, and solve Nexus Grid.</p><b>Read the guide ↗</b></a><a href="/host-a-better-quiz-night.html"><span>02 · PLAY TOGETHER</span><h3>A better quiz night</h3><p>Choose a format, make room for everyone, and keep the evening moving.</p><b>Read the guide ↗</b></a><a href="/how-progress-works.html"><span>03 · YOUR PROGRESS</span><h3>Make every round count</h3><p>A clear guide to XP, achievements, daily challenges, and keeping a progress backup.</p><b>Read the guide ↗</b></a></div></section>'''
    body+='''<section class="h-about" aria-labelledby="about-games-title"><div><span class="h-eyebrow">WELCOME TO THEQUIZREALM</span><h2 id="about-games-title">Free online games.<br>Plenty of ways to play.</h2><p>TheQuizRealm brings together trivia quizzes, word games, logic puzzles, and games to share with friends. Browse by the kind of challenge you enjoy: answer science and geography questions, work through a crossword, find a hidden connection, or see who knows a favourite television series best.</p><p>Each section takes you straight to playable games. Topic collections add background reading and related challenges, while the guides explain actual rules and controls. For a complete list of games and articles, visit the <a href="/directory.html">site directory</a>.</p><a class="h-inline-link" href="/about.html">More about TheQuizRealm ↗</a></div><div class="h-faq"><details><summary>Can I play without creating an account?</summary><p>Yes. Open a game and start playing. The shared player profile saves progress in this browser, with no email address or subscription required.</p></details><details><summary>Which games can I play with friends?</summary><p>Try the <a href="/duel.html">same-device duel</a>, <a href="/minigames.html">Sketch and Guess</a>, or <a href="/group-hub.html">hosted trivia</a>. Hosted rooms need an internet connection; shared-screen games use one device.</p></details><details><summary>How do daily challenges and achievements work?</summary><p>The Daily Ten refreshes at midnight UTC. Your first completion of that daily set earns progress. Achievements come from real saved milestones; the <a href="/how-progress-works.html">progress guide</a> explains the details.</p></details><details><summary>Where are the older games and articles?</summary><p>The <a href="/directory.html">complete directory</a> links to the retained games, regional collections, fandom pages, and articles. Related links on those pages help you continue exploring a topic.</p></details></div></section>'''
    page('index.html','TheQuizRealm — Free Trivia, Word Games & Daily Puzzles','Explore free trivia quizzes, word games, logic puzzles, and games with friends. Browse clear game sections, daily challenges, and topic collections at TheQuizRealm.',body,theme='home')
